package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_append_TriageGen2Test {

    private Element baseElement;

    @Before
    public void setUp() {
        // Create a base element to append to
        baseElement = new Element(Tag.valueOf("div"), "http://example.com", null);
    }

    @Test
    public void testAppendValidHtml() {
        String html = "<p>Hello <b>world</b></p>";
        Element result = baseElement.append(html);
        assertEquals("div", result.tagName());
        assertEquals(3, result.childNodeSize());
    }

    @Test(expected = NullPointerException.class)
    public void testAppendNullHtml() {
        baseElement.append(null);
    }

    @Test
    public void testAppendEmptyHtml() {
        String html = "";
        Element result = baseElement.append(html);
        assertEquals("div", result.tagName());
        assertEquals(0, result.childNodeSize());
    }

    @Test
    public void testAppendWhitespaceHtml() {
        String html = "   ";
        Element result = baseElement.append(html);
        assertEquals("div", result.tagName());
        assertEquals(0, result.childNodeSize());
    }

    @Test
    public void testAppendSingleElementHtml() {
        String html = "<span>Test</span>";
        Element result = baseElement.append(html);
        assertEquals("div", result.tagName());
        assertEquals(1, result.childNodeSize());
        assertEquals("span", result.child(0).tagName());
    }

    @Test
    public void testAppendMultipleElementsHtml() {
        String html = "<p>Para 1</p><p>Para 2</p>";
        Element result = baseElement.append(html);
        assertEquals("div", result.tagName());
        assertEquals(2, result.childNodeSize());
        assertEquals("p", result.child(0).tagName());
        assertEquals("p", result.child(1).tagName());
    }

    @Test
    public void testAppendWithAttributesHtml() {
        String html = "<a href='http://example.com'>Link</a>";
        Element result = baseElement.append(html);
        assertEquals("div", result.tagName());
        assertEquals(1, result.childNodeSize());
        Element link = result.child(0);
        assertEquals("a", link.tagName());
        assertEquals("http://example.com", link.attr("href"));
    }

    @Test
    public void testAppendNestedElementsHtml() {
        String html = "<div><p>Nested</p></div>";
        Element result = baseElement.append(html);
        assertEquals("div", result.tagName());
        assertEquals(1, result.childNodeSize());
        Element childDiv = result.child(0);
        assertEquals("div", childDiv.tagName());
        assertEquals(1, childDiv.childNodeSize());
        assertEquals("p", childDiv.child(0).tagName());
    }

    @Test
    public void testAppendWithTextAndElementsHtml() {
        String html = "Text <p>Paragraph</p>";
        Element result = baseElement.append(html);
        assertEquals("div", result.tagName());
        assertEquals(2, result.childNodeSize());
        assertEquals("Text ", result.child(0).toString());
        assertEquals("p", result.child(1).tagName());
    }

    @Test
    public void testAppendWithInvalidHtml() {
        String html = "<p>Unclosed tag";
        Element result = baseElement.append(html);
        assertEquals("div", result.tagName());
        assertEquals(1, result.childNodeSize());
        assertEquals("p", result.child(0).tagName());
        assertEquals("Unclosed tag", result.child(0).wholeText());
    }
}
